mapper.select:
select '1' as test_id, 1 as line_num, '资金流入-资产端' as col_value1, '资产收息' as col_value2, '' as col_value3, '' as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 2 as line_num, '' as col_value1, '' as col_value2, '债券收息' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10001'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 3 as line_num, '' as col_value1, '' as col_value2, '存款收息' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10002'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
