and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 9 as line_num, '' as col_value1, '' as col_value2, '债券借贷到期' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10008'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 10 as line_num, '' as col_value1, '' as col_value2, '项目类到期' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '1000401'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
