and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 12 as line_num, '' as col_value1, '' as col_value2, '买断式逆回购到期' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10010'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
