and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 14 as line_num, '' as col_value1, '' as col_value2, '债券借贷到期' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10013'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 15 as line_num, '' as col_value1, '融入资产到期' as col_value2, '正回购' as col_value3, (select to_char(round(nvl(t.value, 0),2)) as amount from STT_STRESS_INDDATA t where t.ind_id = '10014'
and t.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 16 as line_num, '资金流出-产品赎回' as col_value1, '轻度' as col_value2, '' as col_value3, (select to_char(round(nvl(ts.light_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 17 as line_num, '' as col_value1, '中度' as col_value2, '' as col_value3, (select to_char(round(nvl(ts.medium_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
union all
select '1' as test_id, 18 as line_num, '' as col_value1, '重度' as col_value2, '' as col_value3, (select to_char(round(nvl(ts.heavy_value, 0),2)) as amount from STT_STRESS_INDDATA t left join STT_INDDATA_LMH ts on t.seq_no=ts.seq_no where t.ind_id = '10011'
and t.test_id=#{flowTestId} and ts.test_id=#{flowTestId}
and t.object_id=#{portfolioId}
) as amount, '' as remarks from sysibm.SYSDUMMY1
order by TEST_ID,LINE_NUM
